/* ===== Аня, 5 класс. Математика — по учебнику Виленкина, Чеснокова, Шварцбурда, Жохова (1990) ===== */
const FR = (a, b) => `${a}/${b}`;
const A_MATH = [
 { id:'m5_1', t:'Натуральные числа. Разряды и классы',
   th:'Многозначное число делят на <b>классы</b> по три цифры справа: единицы, тысячи, миллионы, миллиарды.<br>45 702 318: 45 миллионов 702 тысячи 318. В каждом классе разряды: единицы, десятки, сотни.<br>Округлить до тысяч: смотрим на цифру сотен — если 5 и больше, тысяч становится на одну больше.',
   g: MIX(
     r => { const n=r.int(1e6,99e6), P=[['единиц',0],['десятков',1],['сотен',2],['единиц тысяч',3],['десятков тысяч',4],['сотен тысяч',5],['единиц миллионов',6]], [nm,p]=r.pick(P); return N(`Какая цифра стоит в разряде ${nm} числа ${U.big(n)}?`, Math.floor(n/10**p)%10, ''); },
     r => { const n=r.int(10000,9999999); return N(`Сколько всего тысяч в числе ${U.big(n)}?`, Math.floor(n/1000), 'Отбрасываем последние три цифры'); },
     r => { const a=r.int(1e5,9e6); const b=a+r.pick([1,-1])*r.pick([1,10,100,1000,90000]); return CMP(`Сравни: ${U.big(a)} ? ${U.big(b)}`, a, b, ''); },
     r => { const n=r.int(10000,999999); return N(`Округли ${U.big(n)} до тысяч.`, Math.round(n/1000)*1000, 'Смотрим на цифру сотен'); }
   ) },
 { id:'m5_2', t:'Сложение и вычитание натуральных чисел',
   th:'Переместительное свойство: a + b = b + a. Сочетательное: (a + b) + c = a + (b + c).<br>Удобный порядок: 37 + 289 + 63 = (37 + 63) + 289 = 100 + 289 = 389.<br>Проверка вычитания сложением: 5 000 − 1 237 = 3 763, потому что 3 763 + 1 237 = 5 000.',
   g: MIX(
     r => { const a=r.int(1000,99999), b=r.int(1000,99999); return N(`${U.big(a)} + ${U.big(b)} = ?`, a+b, ''); },
     r => { const a=r.int(10000,99999), b=r.int(1000,a-1); return N(`${U.big(a)} − ${U.big(b)} = ?`, a-b, ''); },
     r => { const a=r.int(11,89), c=100-a, b=r.int(101,899); return N(`Вычисли удобным способом: ${a} + ${b} + ${c}`, a+b+c, `(${a} + ${c}) + ${b} = 100 + ${b}`); }
   ) },
 { id:'m5_3', t:'Буквенные выражения и уравнения',
   th:'В выражение 3a + 5 вместо a подставляем число: при a = 7 получаем 3 · 7 + 5 = 26.<br>Уравнение x + 137 = 500: неизвестное слагаемое x = 500 − 137 = 363.<br>x − 48 = 152: x = 152 + 48 = 200. 250 − x = 175: x = 250 − 175 = 75.',
   g: MIX(
     r => { const k=r.int(2,9), b=r.int(1,30), a=r.int(2,20); return N(`Найди значение выражения ${k}a + ${b} при a = ${a}.`, k*a+b, `${k} · ${a} + ${b}`); },
     r => { const x=r.int(100,900), a=r.int(100,900); return N(`Реши уравнение: x + ${a} = ${x+a}`, x, `x = ${x+a} − ${a}`); },
     r => { const x=r.int(100,900), a=r.int(10,99); return N(`Реши уравнение: x − ${a} = ${x-a}`, x, `x = ${x-a} + ${a}`); },
     r => { const m=r.int(200,999), x=r.int(10,m-50); return N(`Реши уравнение: ${m} − x = ${m-x}`, x, `x = ${m} − ${m-x}`); },
     r => { const k=r.int(3,12), x=r.int(5,60); return N(`Реши уравнение: ${k}x = ${k*x}`, x, `x = ${k*x} : ${k}`); }
   ) },
 { id:'m5_4', t:'Умножение и деление. Свойства',
   th:'Распределительное свойство: (a + b) · c = a · c + b · c. Поэтому 7a + 5a = 12a.<br>Удобно: 25 · 17 · 4 = (25 · 4) · 17 = 100 · 17 = 1 700.<br>Деление проверяем умножением: 1 344 : 32 = 42, так как 42 · 32 = 1 344.',
   g: MIX(
     r => { const a=r.int(101,999), b=r.int(12,99); return N(`${a} · ${b} = ?`, a*b, ''); },
     r => { const d=r.int(12,48), q=r.int(21,199); return N(`${U.big(d*q)} : ${d} = ?`, q, `Проверка: ${q} · ${d} = ${d*q}`); },
     r => { const a=r.int(2,15), b=r.int(2,15); return N(`Упрости: ${a}a + ${b}a = ?·a. Сколько?`, a+b, `(${a} + ${b})a`); },
     r => { const m=r.int(11,99), p=r.pick([[25,4],[50,2],[125,8],[20,5]]); return N(`Вычисли удобно: ${p[0]} · ${m} · ${p[1]}`, p[0]*p[1]*m, `(${p[0]} · ${p[1]}) · ${m} = ${p[0]*p[1]} · ${m}`); }
   ) },
 { id:'m5_5', t:'Порядок действий. Квадрат и куб числа',
   th:'<b>Квадрат</b> числа: 7² = 7 · 7 = 49. <b>Куб</b>: 2³ = 2 · 2 · 2 = 8.<br>Порядок: скобки → степени → умножение и деление → сложение и вычитание.',
   g: MIX(
     r => { const n=r.int(2,20); return N(`${n}² = ?`, n*n, `${n} · ${n}`); },
     r => { const n=r.int(2,6); return N(`${n}³ = ?`, n**3, `${n} · ${n} · ${n}`); },
     r => { const a=r.int(2,9), b=r.int(2,9), c=r.int(2,9); return N(`${a}² + ${b} · ${c} = ?`, a*a+b*c, `${a*a} + ${b*c}`); },
     r => { const a=r.int(20,99), b=r.int(2,9), c=r.int(2,9), d=r.int(Math.max(1,b*c-a),b*c); return N(`${a} − (${b} · ${c} − ${d}) = ?`, a-(b*c-d), `В скобках: ${b*c} − ${d} = ${b*c-d}`); }
   ) },
 { id:'m5_6', t:'Площадь. Единицы площади',
   th:'Площадь прямоугольника <b>S = a · b</b>, квадрата — <b>S = a²</b>.<br>1 м² = 100 дм² = 10 000 см². 1 ар (сотка) = 100 м². 1 га = 10 000 м².',
   g: MIX(
     r => { const a=r.int(3,40), b=r.int(3,40); return N(`Длина комнаты ${a} м, ширина ${b} м. Найди площадь (м²).`, a*b, `${a} · ${b}`); },
     r => { const m=r.int(2,9); return N(`${m} м² = ? дм²`, m*100, '1 м² = 100 дм²'); },
     r => { const h=r.int(2,9); return N(`${h} га = ? м²`, h*10000, '1 га = 10 000 м²'); },
     r => { const s=r.int(2,15), a=r.pick([10,20,25,50].filter(x=>s*100%x===0)), b=s*100/a; return N(`Участок прямоугольной формы ${a} м × ${b} м. Сколько это соток (1 сотка = 100 м²)?`, s, `${a} · ${b} = ${a*b} м²`); }
   ) },
 { id:'m5_7', t:'Объём прямоугольного параллелепипеда',
   th:'<b>V = a · b · c</b>. Объём куба V = a³.<br>1 дм³ = 1 литр = 1 000 см³. 1 м³ = 1 000 дм³.',
   g: MIX(
     r => { const a=r.int(2,12), b=r.int(2,12), c=r.int(2,12); return N(`Найди объём коробки ${a} см × ${b} см × ${c} см (см³).`, a*b*c, `${a} · ${b} · ${c}`); },
     r => { const a=r.int(2,8)*10, b=r.int(2,6)*10, c=r.int(2,6)*10; return N(`Аквариум ${a} см × ${b} см × ${c} см. Сколько литров воды в нём помещается?`, a*b*c/1000, `${a/10} · ${b/10} · ${c/10} дм³`); },
     r => { const a=r.int(2,9); return N(`Ребро куба ${a} дм. Найди объём (дм³).`, a**3, `${a}³`); }
   ) },
 { id:'m5_8', t:'Обыкновенные дроби',
   th:'Дробь <b>3/4</b>: целое разделили на 4 равные части (знаменатель) и взяли 3 (числитель).<br>Найти 3/4 от 48: 48 : 4 · 3 = 36.<br>Дробь <b>правильная</b>, если числитель меньше знаменателя (3/4), и <b>неправильная</b>, если больше или равен (7/4 = 1 3/4).',
   g: MIX(
     r => { const d=r.pick([2,3,4,5,6,8,10]), n=r.int(1,d-1), k=r.int(2,12); return N(`Найди ${FR(n,d)} от ${d*k}.`, n*k, `${d*k} : ${d} · ${n}`); },
     r => { const d=r.int(5,12), a=r.int(1,d-1), b=r.int(1,d-1); return CMP(`Сравни дроби: ${FR(a,d)} ? ${FR(b,d)}`, a, b, 'У дробей с одинаковыми знаменателями больше та, у которой больше числитель'); },
     r => { const d=r.int(3,9); const good=FR(d+r.int(1,5),d); return C('Какая дробь неправильная?', good, [FR(1,d), FR(d-1,d), FR(2,d+1)], 'Числитель больше знаменателя'); },
     r => { const d=r.int(2,9), w=r.int(1,5), n=r.int(1,d-1); return C(`Выдели целую часть: ${FR(w*d+n,d)}`, `${w} ${FR(n,d)}`, [`${w+1} ${FR(n,d)}`, `${w} ${FR(d-n,d)}`, `${n} ${FR(w,d)}`], `${w*d+n} : ${d} = ${w} (ост. ${n})`); }
   ) },
 { id:'m5_9', t:'Сложение и вычитание дробей с одинаковыми знаменателями',
   th:'Складываем числители, знаменатель оставляем: 2/7 + 3/7 = 5/7.<br>Смешанные числа: целые с целыми, дроби с дробями: 2 3/7 + 1 2/7 = 3 5/7.',
   g: MIX(
     r => { const d=r.int(5,15), a=r.int(1,d-2), b=r.int(1,d-1-a); return C(`${FR(a,d)} + ${FR(b,d)} = ?`, FR(a+b,d), [FR(a+b,d+d), FR(a*b,d), FR(a+b+1,d)], 'Знаменатель не меняется'); },
     r => { const d=r.int(5,15), a=r.int(3,d-1), b=r.int(1,a-1); return C(`${FR(a,d)} − ${FR(b,d)} = ?`, FR(a-b,d), [FR(a-b,0||d*2), FR(a+b,d), FR(a-b+1,d)], 'Вычитаем числители'); },
     r => { const d=r.int(5,11), w1=r.int(1,5), w2=r.int(1,4), a=r.int(1,d-2), b=r.int(1,d-1-a); return C(`${w1} ${FR(a,d)} + ${w2} ${FR(b,d)} = ?`, `${w1+w2} ${FR(a+b,d)}`, [`${w1+w2+1} ${FR(a+b,d)}`, `${w1+w2} ${FR(a+b,2*d)}`, `${w1*w2} ${FR(a+b,d)}`], 'Целые с целыми, дроби с дробями'); }
   ) },
 { id:'m5_10', t:'Десятичные дроби. Сравнение и округление',
   th:'0,7 = 7/10, 0,35 = 35/100, 3,125 = 3 125/1000.<br>Сравниваем по разрядам: 0,7 &gt; 0,65, потому что 7 десятых больше 6 десятых. Нули в конце не меняют дробь: 0,5 = 0,50.<br>Округлить 3,47 до десятых: смотрим на сотые (7 ≥ 5) — получаем 3,5.',
   g: MIX(
     r => { const a=r.int(10,99)/100, b=r.int(1,9)/10; return CMP(`Сравни: ${U.dec(a)} ? ${U.dec(b)}`, a, b, 'Сравниваем десятые, потом сотые'); },
     r => { const x=r.int(101,999)/100; return N(`Округли ${U.dec(x)} до десятых.`, Math.round(x*10)/10, 'Смотрим на цифру сотых'); },
     r => { const n=r.int(11,99); return C(`Запиши десятичной дробью: ${n}/100`, U.dec(n/100), [U.dec(n/10), U.dec(n/1000), `${n},100`], ''); },
     r => { const n=r.int(11,99); return N(`Сколько сотых в числе ${U.dec(n/100)}?`, n, ''); }
   ) },
 { id:'m5_11', t:'Сложение и вычитание десятичных дробей',
   th:'Записываем столбиком <b>запятая под запятой</b>, уравниваем число знаков нулями: 3,7 + 2,45 = 3,70 + 2,45 = 6,15.<br>Ответ можно вводить с запятой.',
   g: MIX(
     r => { const a=r.int(10,999)/10, b=r.int(10,999)/100; return N(`${U.dec(a)} + ${U.dec(b)} = ?`, Math.round((a+b)*100)/100, 'Запятая под запятой'); },
     r => { const a=r.int(500,999)/10, b=r.int(10,499)/100; return N(`${U.dec(a)} − ${U.dec(b)} = ?`, Math.round((a-b)*100)/100, 'Допиши нуль: ' + U.dec(a) + '0'); }
   ) },
 { id:'m5_12', t:'Умножение и деление десятичных на натуральные числа',
   th:'Умножаем, не обращая внимания на запятую, потом отделяем столько знаков, сколько было: 2,35 · 4 = 9,40 = 9,4.<br>Умножить на 10, 100, 1000 — перенести запятую вправо на 1, 2, 3 знака. Делить — влево.',
   g: MIX(
     r => { const a=r.int(11,99)/10, n=r.int(2,9); return N(`${U.dec(a)} · ${n} = ?`, Math.round(a*n*100)/100, ''); },
     r => { const q=r.int(11,99)/10, n=r.int(2,9); return N(`${U.dec(Math.round(q*n*100)/100)} : ${n} = ?`, q, `Проверка: ${U.dec(q)} · ${n}`); },
     r => { const a=r.int(101,999)/100, k=r.pick([10,100,1000]); return N(`${U.dec(a)} · ${k} = ?`, Math.round(a*k*100)/100, 'Переносим запятую вправо'); },
     r => { const a=r.int(11,999)/10, k=r.pick([10,100]); return N(`${U.dec(a)} : ${k} = ?`, Math.round(a/k*10000)/10000, 'Переносим запятую влево'); }
   ) },
 { id:'m5_13', t:'Умножение десятичных дробей',
   th:'Умножаем как натуральные числа, а в ответе отделяем запятой столько знаков, сколько их в обоих множителях вместе: 1,5 · 0,4 = 0,60 = 0,6.',
   g: r => { const a=r.int(2,99)/10, b=r.int(2,9)/10; return N(`${U.dec(a)} · ${U.dec(b)} = ?`, Math.round(a*b*1000)/1000, `${Math.round(a*10)} · ${Math.round(b*10)} = ${Math.round(a*10)*Math.round(b*10)}, отделяем 2 знака`); } },
 { id:'m5_14', t:'Проценты',
   th:'<b>Процент</b> — сотая часть числа. 1% = 0,01.<br>25% от 80: 80 · 0,25 = 20. 10% — это десятая часть, 50% — половина, 25% — четверть.<br>Сколько процентов 15 составляет от 60: 15 : 60 = 0,25 = 25%.',
   g: MIX(
     r => { const p=r.pick([5,10,20,25,50,75]), base=r.int(1,20)*20; return N(`Найди ${p}% от ${base}.`, base*p/100, `${base} · ${p/100}`.replace('.',',')); },
     r => { const p=r.pick([10,20,25,50,75]), base=r.int(2,10)*20; return N(`Сколько процентов составляет ${base*p/100} от ${base}?`, p, `${base*p/100} : ${base} = ${p/100}`.replace('.',',')); },
     r => { const p=r.pick([10,20,25,50]), price=r.int(2,20)*20; return N(`Книга стоила ${price} €. Цену снизили на ${p}%. Сколько стоит книга теперь?`, price*(100-p)/100, `${price} − ${price*p/100}`); }
   ) },
 { id:'m5_15', t:'Углы. Транспортир',
   th:'<b>Прямой</b> угол = 90°. <b>Острый</b> — меньше 90°. <b>Тупой</b> — больше 90°, но меньше 180°. <b>Развёрнутый</b> = 180°.<br>Если развёрнутый угол разделить лучом, сумма двух углов = 180°.',
   g: MIX(
     r => { const v=r.pick([r.int(5,89),90,r.int(91,179),180]); const a=v<90?'острый':v===90?'прямой':v<180?'тупой':'развёрнутый'; return C(`Какой угол в ${v}°?`, a, ['острый','прямой','тупой','развёрнутый'], ''); },
     r => { const a=r.int(10,170); return N(`Развёрнутый угол разделили лучом. Один из углов ${a}°. Найди другой.`, 180-a, `180° − ${a}°`); },
     r => { const a=r.int(10,80); return N(`Прямой угол разделили лучом. Один из углов ${a}°. Найди другой.`, 90-a, `90° − ${a}°`); }
   ) },
 { id:'m5_16', t:'Среднее арифметическое',
   th:'<b>Среднее арифметическое</b> = сумма чисел : их количество. (4 + 7 + 10) : 3 = 7.<br>Средняя скорость = весь путь : всё время.',
   g: MIX(
     r => { const n=r.int(3,5), m=r.int(5,40); let xs=[]; let s=0; for(let i=0;i<n-1;i++){const x=m+r.int(-5,5);xs.push(x);s+=x;} xs.push(m*n-s); return N(`Найди среднее арифметическое: ${xs.join(', ')}`, m, `Сумма ${m*n} : ${n}`); },
     r => { const v1=r.pick([40,50,60]), v2=r.pick([70,80,90]), t1=2, t2=1; const S=v1*t1+v2*t2; if (S%3) return N(`Найди среднее арифметическое: 12, 15, 18`, 15, ''); return N(`Машина ехала ${t1} ч со скоростью ${v1} км/ч и ${t2} ч со скоростью ${v2} км/ч. Найди среднюю скорость (км/ч).`, S/3, `(${v1*t1} + ${v2}) : 3`); }
   ) }
];

/* ===== Русский язык — по учебнику Ладыженской, Баранова и др. для 5–6 классов ===== */
const A_RUS = [
 { id:'r5_1', t:'Главные члены предложения',
   th:'<b>Подлежащее</b> отвечает на вопрос кто? что? и обозначает, о ком или о чём говорится.<br><b>Сказуемое</b> — что делает предмет (что делает? что сделал? какой он?).',
   g: B(['«Утром над рекой поднялся туман». Подлежащее —|туман|рекой;утром;поднялся','«Мой брат читает интересную книгу». Сказуемое —|читает|брат;книгу;интересную','«В саду зацвели яблони». Подлежащее —|яблони|саду;зацвели;в саду','«Скоро наступит весна». Сказуемое —|наступит|весна;скоро;нет сказуемого','«Над городом летят журавли». Подлежащее —|журавли|городом;летят;над','«Вечером мы пошли на пляж». Сказуемое —|пошли|мы;вечером;пляж','«Ветер гнал по небу тучи». Подлежащее —|ветер|тучи;небу;гнал']) },
 { id:'r5_2', t:'Однородные члены. Запятые',
   th:'Однородные члены отвечают на один вопрос и относятся к одному слову: <i>Росли яблони, груши и сливы.</i><br>Перед <b>а, но</b> запятая ставится всегда. Перед одиночным <b>и</b> — не ставится.',
   g: B(['Где нужна запятая: «В саду росли яблони груши и сливы»?|после «яблони»|после «груши»;после «росли»;не нужна','Где нужна запятая: «Ветер шумел но дождя не было»?|перед «но»|после «ветер»;перед «дождя»;не нужна','Где нужна запятая: «Мы купили хлеб и молоко»?|не нужна|перед «и»;после «купили»;после «хлеб»','Где нужна запятая: «День был тёплый но пасмурный»?|перед «но»|перед «тёплый»;после «день»;не нужна','Где нужна запятая: «Не ветер а солнце разбудило меня»?|перед «а»|после «солнце»;после «разбудило»;не нужна','Где нужна запятая: «Аня читала рисовала и пела»?|после «читала»|после «рисовала»;перед «и»;не нужна']) },
 { id:'r5_3', t:'Обращение',
   th:'<b>Обращение</b> — слово, которым называют того, к кому обращаются. Выделяется запятыми: <i>Мама, посмотри!</i> <i>Расскажи, Аня, что ты прочитала.</i> Обращение не является членом предложения.',
   g: B(['Найди обращение: «Мама, посмотри на радугу!»|мама|радугу;посмотри;на','Найди обращение: «Расскажи, Аня, что ты прочитала»|Аня|расскажи;что;прочитала','Найди обращение: «Здравствуй, лес!»|лес|здравствуй;нет обращения','Найди обращение: «Друзья, пойдёмте в поход»|друзья|поход;пойдёмте;в','Есть ли обращение: «Аня пошла в школу»?|нет|да, Аня;да, школу;да, пошла','Где запятая: «Ребята идите обедать»?|после «Ребята»|после «идите»;не нужна;перед «Ребята»']) },
 { id:'r5_4', t:'Лексика: синонимы, антонимы, фразеологизмы',
   th:'<b>Синонимы</b> — близкие по смыслу слова (храбрый — смелый). <b>Антонимы</b> — противоположные (горячий — холодный).<br><b>Фразеологизм</b> — устойчивое выражение: «бить баклуши» = бездельничать.<br>Есть <b>устаревшие</b> слова (око — глаз) и <b>заимствованные</b> (компьютер, футбол; «мармелад» пришёл из португальского: marmelada — от marmelo, айва).',
   g: B(['Синоним к слову «храбрый»|смелый|трусливый;весёлый;тихий','Антоним к слову «горячий»|холодный|тёплый;жаркий;мокрый','Синоним к слову «грустный»|печальный|радостный;громкий;быстрый','Антоним к слову «враг»|друг|недруг;сосед;соперник','Что значит «бить баклуши»?|бездельничать|работать;драться;играть в мяч','Что значит «водить за нос»?|обманывать|гулять;помогать;лечить','Что значит «как две капли воды»?|очень похожи|очень мокрые;очень мало;совсем разные','Что значит устаревшее слово «око»?|глаз|ухо;рука;окно','Слово «мармелад» по происхождению — из какого языка?|из португальского|из китайского;из японского;это исконно русское слово|Португальское marmelada — повидло из айвы (marmelo). В русский язык слово пришло через французский и немецкий','Что значит «с гулькин нос»?|очень мало|очень много;очень длинный;быстро']) },
 { id:'r5_5', t:'Чередование о/а в корнях',
   th:'<b>-лаг-/-лож-</b>: перед г пишем а, перед ж — о (положить, излагать).<br><b>-раст-/-ращ-/-рос-</b>: перед ст, щ — а, иначе о (растение, выросли; исключения: росток, отрасль).<br><b>-гар-/-гор-</b>: без ударения — о (загорать), под ударением — как слышим (загар).<br><b>-кас-/-кос-</b>: если после корня суффикс -а-, пишем а (касаться), иначе о (коснуться).',
   g: B(['Вставь: пол_жить|о|а','Вставь: изл_гать|а|о','Вставь: р_стение|а|о','Вставь: выр_сли|о|а','Вставь: р_сток|о|а|исключение','Вставь: заг_рать|о|а','Вставь: заг_р (под ударением)|а|о','Вставь: к_саться|а|о','Вставь: к_снуться|о|а','Вставь: предл_жение|о|а']) },
 { id:'r5_6', t:'Буквы ы и и после приставок',
   th:'После приставок на согласный вместо <b>и</b> пишем <b>ы</b>: предыстория, розыгрыш, сыграть, подытожить.<br>Исключения: взимать, сверх- и меж- (сверхинтересный, межинститутский). После приставок на гласный — <b>и</b>: поиграть.',
   g: B(['Вставь: пред_стория|ы|и','Вставь: раз_грать|ы|и','Вставь: без_нтересный|ы|и','Вставь: под_тожить|ы|и','Вставь: с_грать|ы|и','Вставь: сверх_нтересный|и|ы','Вставь: вз_мать|и|ы','Вставь: по_грать|и|ы','Вставь: меж_нститутский|и|ы']) },
 { id:'r5_7', t:'Приставки пре- и при-',
   th:'<b>При-</b>: приближение (приехать), присоединение (пришить), близость (приморский), неполнота действия (приоткрыть).<br><b>Пре-</b>: «очень» (прекрасный = очень красивый) или «пере-» (преградить = перегородить, прервать = перервать).',
   g: B(['Вставь: пр_ехать|и|е','Вставь: пр_красный|е|и','Вставь: пр_морский|и|е','Вставь: пр_одолеть|е|и','Вставь: пр_шить|и|е','Вставь: пр_землиться|и|е','Вставь: пр_рвать (= перервать)|е|и','Вставь: пр_открыть (немного)|и|е','Вставь: пр_мудрый (очень мудрый)|е|и','Вставь: пр_школьный|и|е']) },
 { id:'r5_8', t:'Несклоняемые существительные и их род',
   th:'Несклоняемые слова не меняются по падежам: пальто, кофе, метро, кино.<br>Неодушевлённые обычно среднего рода (пальто, метро), но <b>кофе</b> — мужского. Животные — мужского (кенгуру, какаду). Род географического названия — по слову «город, река, озеро»: Сочи (город) — м.р., Миссисипи (река) — ж.р.',
   g: B(['Какого рода «кофе»?|мужского|среднего;женского','Какого рода «пальто»?|среднего|мужского;женского','Какого рода «метро»?|среднего|мужского;женского','Какого рода «кенгуру»?|мужского|среднего;женского','Какого рода «Миссисипи» (река)?|женского|мужского;среднего','Какого рода «Тбилиси» (город)?|мужского|женского;среднего','Как правильно?|чёрный кофе|чёрное кофе;чёрная кофе','Как правильно?|новое пальто|новый пальто;новая пальто']) },
 { id:'r5_9', t:'НЕ с существительными',
   th:'<b>Слитно</b>: если без не слово не употребляется (невежда, неряха, негодование) или его можно заменить синонимом без не (неправда = ложь, неприятель = враг).<br><b>Раздельно</b>: при противопоставлении с союзом а (не правда, а ложь).',
   g: B(['Как пишется: (не)вежда|слитно|раздельно','Как пишется: (не)правда (= ложь)|слитно|раздельно','Как пишется: (не)правда, а ложь|раздельно|слитно','Как пишется: (не)приятель (= враг)|слитно|раздельно','Как пишется: (не)годование|слитно|раздельно','Как пишется: (не)друг, а враг|раздельно|слитно','Как пишется: (не)погода|слитно|раздельно','Как пишется: (не)ряха|слитно|раздельно']) },
 { id:'r5_10', t:'Суффиксы -чик- и -щик-',
   th:'После <b>д, т, з, с, ж</b> пишем <b>-чик</b>: разведчик, переводчик, заказчик, лётчик, перебежчик.<br>В остальных случаях <b>-щик</b>: каменщик, банщик, барабанщик, кровельщик.',
   g: B(['Вставь: развед_ик|ч|щ','Вставь: камен_ик|щ|ч','Вставь: перевод_ик|ч|щ','Вставь: бан_ик|щ|ч','Вставь: перебеж_ик|ч|щ','Вставь: барабан_ик|щ|ч','Вставь: заказ_ик|ч|щ','Вставь: лёт_ик|ч|щ','Вставь: кровель_ик|щ|ч']) },
 { id:'r5_11', t:'Н и НН в суффиксах прилагательных',
   th:'<b>-ан-, -ян-, -ин-</b> — одна н: кожаный, глиняный, лебединый. Исключения: стеклянный, оловянный, деревянный.<br><b>-онн-, -енн-</b> — две н: станционный, клюквенный. Исключение: ветреный.<br>Корень на н + суффикс н — нн: карманный, лимонный.',
   g: B(['Вставь: кожа_ый|н|нн','Вставь: стекля_ый|нн|н','Вставь: глиня_ый|н|нн','Вставь: деревя_ый|нн|н','Вставь: клюкве_ый|нн|н','Вставь: ветре_ый|н|нн','Вставь: лебеди_ый|н|нн','Вставь: карма_ый|нн|н','Вставь: соломе_ый|нн|н','Вставь: серебря_ый|н|нн','Вставь: лимо_ый|нн|н']) },
 { id:'r5_12', t:'Степени сравнения прилагательных',
   th:'Сравнительная степень: выше, красивее, <b>более</b> красивый. Превосходная: <b>самый</b> высокий, высочайший.<br>Особые формы: хороший — лучше, плохой — хуже, маленький — меньше.<br>Ошибка: «более красивее» — так нельзя.',
   g: B(['Сравнительная степень от «хороший»|лучше|хорошее;хорошее всех;более хорошее','Сравнительная степень от «плохой»|хуже|плохее;плохше;более плохее','Сравнительная степень от «маленький»|меньше|маленьче;малее;маленькее','Какая форма неправильная?|более красивее|красивее;более красивый;самый красивый','«Самый высокий» — это степень…|превосходная|сравнительная;положительная;краткая','Сравнительная степень от «высокий»|выше|высокее;высче;высокей']) },
 { id:'r5_13', t:'Мягкий знак в числительных',
   th:'От 5 до 20 и 30 — <b>ь на конце</b>: пятнадцать, тридцать.<br>От 50 до 80 и от 500 до 900 — <b>ь в середине</b>: пятьдесят, шестьсот.<br>В середине слов на -надцать ь нет: пятнадцать.',
   g: B(['Вставь: пят_десят|ь|без ь','Вставь: пятнадцат_|ь|без ь','Вставь: шест_сот|ь|без ь','Вставь: семнадцат_|ь|без ь','Вставь: девят_сот|ь|без ь','Вставь: тридцат_|ь|без ь','Вставь: пят_надцать|без ь|ь','Вставь: восем_десят|ь|без ь','Вставь: четырнадцат_|ь|без ь']) },
 { id:'r5_14', t:'Разряды местоимений',
   th:'Личные: я, ты, он. Возвратное: себя. Притяжательные: мой, твой, свой. Вопросительные: кто? что? какой? Указательные: этот, тот, такой. Определительные: весь, каждый, сам. Отрицательные: никто, ничего. Неопределённые: кто-то, некто.',
   g: r => { const W=[['себя','возвратное'],['мой','притяжательное'],['кто-то','неопределённое'],['никто','отрицательное'],['этот','указательное'],['весь','определительное'],['я','личное'],['каждый','определительное'],['ничего','отрицательное'],['твой','притяжательное'],['тот','указательное'],['некто','неопределённое']]; const [w,a]=r.pick(W); const all=['личное','возвратное','притяжательное','указательное','определительное','отрицательное','неопределённое']; return C(`Разряд местоимения «${w}»`, a, r.sample(all.filter(x=>x!==a),3), ''); } },
 { id:'r5_15', t:'-тся и -ться в глаголах',
   th:'Задай вопрос к глаголу. <b>Что делать?</b> — пишем <b>-ться</b> (надо учиться). <b>Что делает?</b> — <b>-тся</b> (он учится).',
   g: B(['Вставь: Он хорошо учи_ся.|тся|ться','Вставь: Надо учи_ся.|ться|тся','Вставь: Мальчик хочет научи_ся плавать.|ться|тся','Вставь: Солнце сади_ся.|тся|ться','Вставь: Не стоит волнова_ся.|ться|тся','Вставь: Вода в чайнике грее_ся.|тся|ться','Вставь: Пора собира_ся в школу.|ться|тся','Вставь: Дверь легко открывае_ся.|тся|ться']) },
 { id:'r5_16', t:'Наклонения глагола',
   th:'<b>Изъявительное</b> — действие происходит на самом деле: читаю, читал, буду читать.<br><b>Условное</b> — при условии, с частицей бы: читал бы.<br><b>Повелительное</b> — просьба, приказ: читай!',
   g: r => { const W=[['читаю','изъявительное'],['прочитал бы','условное'],['прочитай','повелительное'],['пойду (завтра в кино)','изъявительное'],['напишите','повелительное'],['пошёл бы','условное'],['буду рисовать','изъявительное'],['не шумите','повелительное'],['помог бы','условное']]; const [w,a]=r.pick(W); return C(`Наклонение глагола «${w}»`, a, ['изъявительное','условное','повелительное'], ''); } },
 { id:'r5_17', t:'Части речи (обобщение)',
   th:'Существительное — кто? что? Прилагательное — какой? Глагол — что делать? Наречие — как? где? когда? Числительное — сколько? который? Местоимение указывает, не называя.',
   g: r => { const W=[['радость','существительное'],['радостный','прилагательное'],['радоваться','глагол'],['радостно (улыбнулся)','наречие'],['семь','числительное'],['они','местоимение'],['тишина','существительное'],['тихий','прилагательное'],['затихать','глагол'],['тихо (сказал)','наречие'],['вчера','наречие'],['сорок','числительное'],['себя','местоимение'],['весёлый','прилагательное'],['веселиться','глагол']]; const [w,a]=r.pick(W); const all=['существительное','прилагательное','глагол','наречие','числительное','местоимение']; return C(`Какая часть речи «${w}»?`, a, r.sample(all.filter(x=>x!==a),3), ''); } }
];

/* ===== История Древнего мира — по учебнику Ф. П. Коровкина (1984), без идеологии ===== */
const A_HIST = [
 { id:'h5_1', t:'Счёт лет в истории. Века',
   th:'Счёт лет <b>нашей эры</b> (н. э.) ведётся от Рождества Христова. (Римляне считали годы от основания Рима, греки — по Олимпиадам.) Годы <b>до нашей эры</b> (до н. э.) считают в обратную сторону: чем больше число, тем давнее событие. 776 г. до н. э. был раньше, чем 509 г. до н. э.<br><b>Век</b> — 100 лет. 1–100 гг. — I век, 101–200 — II век. Год 1492 — XV век: отбрасываем две последние цифры и прибавляем 1 (если год не круглая сотня; 1500 г. — последний год XV века). Века до н. э. считают так же, только в обратную сторону.',
   g: (() => { const yr = y => y < 0 ? `${-y} г. до н. э.` : `${y} г.`, cen = y => y < 0 ? U.roman(Math.ceil(-y / 100)) + ' в. до н. э.' : U.roman(Math.ceil(y / 100)) + ' в.';
     /* Хронология — на событиях, которые Аня проходит в курсе */
     const EV = [[-2560,'построили пирамиду Хеопса'],[-1750,'Хаммурапи записал законы'],[-776,'прошли первые Олимпийские игры'],[-753,'по легенде, основан Рим'],[-509,'в Риме возникла республика'],[-490,'греки победили персов при Марафоне'],[-336,'Александр Македонский стал царём'],[-218,'Ганнибал перешёл Альпы'],[-146,'римляне разрушили Карфаген'],[-44,'убит Юлий Цезарь'],[476,'пала Западная Римская империя'],[800,'Карл Великий стал императором'],[988,'крещение Руси'],[1143,'Португалия стала королевством'],[1492,'Колумб доплыл до Америки']];
     const pick4 = r => r.sample(EV.slice(0, 11), 4);
     return MIX(
     r => { const y=r.int(101,2099), c=Math.ceil(y/100), rnd=y%100===0; return C(`В каком веке был ${y} год?`, U.roman(c), [U.roman(c-1), U.roman(c+1), U.roman(c+2)], rnd ? `${y} — круглая сотня, это последний год ${U.roman(c)} века` : `${y}: ${Math.floor(y/100)} + 1 = ${c}`); },
     r => { const y=r.int(1,9)*100+r.int(1,99); const c=Math.ceil(y/100); return C(`В каком веке был ${y} г. до н. э.?`, U.roman(c)+' в. до н. э.', [U.roman(c+1)+' в. до н. э.', U.roman(c)+' в. н. э.', U.roman(c-1)+' в. до н. э.'], `Века до н. э. считают так же: ${y} → ${Math.floor(y/100)} + 1 = ${c}`); },
     r => { const ev = pick4(r), s = ev.slice().sort((x, y) => x[0] - y[0]); return C('Какое событие произошло <b>раньше</b> всех?', `${s[0][1]} (${yr(s[0][0])})`, s.slice(1).map(e => `${e[1]} (${yr(e[0])})`), 'По порядку: ' + s.map(e => `${yr(e[0])} — ${e[1]}`).join('; ')); },
     r => { const ev = pick4(r), s = ev.slice().sort((x, y) => y[0] - x[0]); return C('Какое событие произошло <b>позже</b> всех?', `${s[0][1]} (${yr(s[0][0])})`, s.slice(1).map(e => `${e[1]} (${yr(e[0])})`), 'По порядку: ' + s.slice().reverse().map(e => `${yr(e[0])} — ${e[1]}`).join('; ')); },
     r => { const [y, t] = r.pick(EV.filter(e => e[0] % 100 !== 0)), c = Math.ceil(Math.abs(y) / 100), bc = y < 0, era = bc ? ' в. до н. э.' : ' в.';
       return C(`Событие: ${t}, ${yr(y)} В каком веке это было?`, cen(y), [U.roman(c + 1) + era, U.roman(c - 1 || c + 2) + era, U.roman(c) + (bc ? ' в. н. э.' : ' в. до н. э.')], `${Math.abs(y)}: ${Math.floor(Math.abs(y) / 100)} + 1 = ${c}` + (bc ? ', и это до нашей эры' : '')); },
     r => { const a=r.int(4,9)*100, b=a-r.int(1,3)*100; return C(`От ${a} г. до н. э. до ${b} г. до н. э. прошло…`, `${a-b} лет`, [`${a+b} лет`, `${a-b+100} лет`, `${a-b-100 || a+b+100} лет`], `До н. э. годы идут на убыль, поэтому вычитаем: ${a} − ${b} = ${a-b}`); },
     r => { const a=r.int(2,15)*100+r.int(1,99), b=r.int(1,9)*100+r.int(1,99); return C('Что было раньше?', `${a} г. до н. э.`, [`${b} г. н. э.`, `${a} г. н. э.`, `${Math.max(1,a-r.int(100,180))} г. до н. э.`], 'Чем больше число до н. э., тем дальше от нас это событие'); },
     B(['От какого события ведётся счёт лет нашей эры?|от Рождества Христова|от основания Рима;от первых Олимпийских игр;от постройки пирамид|Римляне считали годы от основания Рима, греки — по Олимпиадам, а мы — от Рождества Христова','Один век — это…|сто лет|десять лет;тысяча лет;пятьдесят лет','Как записать римскими цифрами двадцатый век?|XX в.|XIX в.;XXI в.;IIXX в.','Что было раньше: основание Рима (753 г. до н. э.) или разрушение Карфагена (146 г. до н. э.)?|основание Рима|разрушение Карфагена;они были в один год|Чем больше число до н. э., тем раньше','Колумб доплыл до Америки в 1492 г. В каком веке?|XV|XIV;XVI;XIX','Португалия стала королевством в 1143 г. Это какой век?|XII|XI;XIII;XIV','Тысячелетие — это…|тысяча лет|сто лет;десять лет;десять тысяч лет','Мы живём в 2026 году. Какой сейчас век?|XXI|XX;XXII;XIX','Как пишут «пятый век» в учебнике истории?|V в.|5 в.;IIIII в.;VV в.','Пирамиду Хеопса построили около 2560 г. до н. э. Это какой век?|XXVI в. до н. э.|XXV в. до н. э.;XXVI в. н. э.;II в. до н. э.'])
   ); })() },
 { id:'h5_2', t:'Первобытные собиратели и охотники',
   th:'Древнейшие люди жили группами, собирали плоды и охотились. Орудия делали из камня, дерева, кости. Огонь научились поддерживать, а потом добывать трением.<br>Во время ледникового периода охотились на мамонтов, шили одежду из шкур, рисовали животных на стенах пещер (пещера Альтамира в Испании), выбивали их изображения на скалах (долина Коа в Португалии). Огонь добывали трением дерева о дерево или высекали искры ударом камня о камень.',
   g: B(['Из чего делали первые орудия труда?|из камня, дерева и кости|из железа;из бронзы;из пластмассы','Чем занимались древнейшие люди?|собирательством и охотой|торговлей;земледелием на полях;ремеслом в городах','Где в Португалии сохранились древние изображения животных на скалах?|в долине Коа|в Лиссабоне;на Азорах;на Мадейре','На кого охотились в ледниковый период?|на мамонтов|на динозавров;на кенгуру;на домашних коров|Динозавры вымерли за миллионы лет до появления людей','Как древние люди добывали огонь?|трением и высеканием искр|спичками;зажигалкой;линзой из стекла','Пещера Альтамира с рисунками находится в…|Испании|Египте;Китае;Греции']) },
 { id:'h5_3', t:'Земледельцы и скотоводы. Металлы',
   th:'Около 10 тысяч лет назад люди начали выращивать растения и приручать животных — появились <b>земледелие</b> и <b>скотоводство</b>. Люди стали жить оседло, в посёлках.<br>Появились ремёсла: гончарство, ткачество. Первым металлом была медь, затем <b>бронза</b> (медь + олово), позже <b>железо</b>.',
   g: B(['Что такое земледелие?|выращивание растений|охота на зверей;рыбалка;торговля','Бронза — это сплав…|меди и олова|железа и угля;золота и серебра;глины и песка','Какой металл люди начали использовать первым?|медь|железо;алюминий;сталь','Что изменилось, когда люди стали земледельцами?|они стали жить оседло|они стали кочевать;они перестали работать;они переселились в пещеры','Кто такой гончар?|мастер, который делает посуду из глины|охотник;пастух;воин','Какое животное одним из первых приручил человек?|собаку|льва;слона;кенгуру']) },
 { id:'h5_4', t:'Древний Египет',
   th:'Египет лежит в долине <b>Нила</b>. Разливы реки приносили плодородный ил. Царём был <b>фараон</b>. Для фараона Хеопса около 2560 г. до н. э. построили пирамиду высотой около 146 м.<br>Египтяне писали <b>иероглифами</b> на <b>папирусе</b>, знали календарь из 365 дней. Иероглифы прочитал француз Шампольон в 1822 г. по Розеттскому камню.',
   g: B(['Почему земля в долине Нила была плодородной?|разливы приносили ил|там часто шли дожди;её удобряли химией;там были леса','Как называли царя Египта?|фараон|император;консул;султан','Чья пирамида — самая большая?|Хеопса|Тутанхамона;Рамсеса II;Клеопатры','Кто расшифровал египетские иероглифы?|Шампольон|Геродот;Колумб;Гомер','На чём писали египтяне?|на папирусе|на глиняных табличках;на бумаге;на шёлке','Сколько дней было в египетском году?|365|360;300;100|12 месяцев по 30 дней и ещё 5 праздничных дней']) },
 { id:'h5_5', t:'Западная Азия: Междуречье, Финикия, Персия',
   th:'<b>Междуречье</b> (Месопотамия) — между реками Тигр и Евфрат. Писали <b>клинописью</b> на глиняных табличках. Царь Вавилона <b>Хаммурапи</b> записал законы на каменном столбе (около 1750 г. до н. э.).<br><b>Финикийцы</b> — мореплаватели и торговцы, придумали <b>алфавит</b> из 22 букв, от него произошли греческий и латинский.<br>Персидская держава была огромной; цари строили дороги и почту.',
   g: B(['Между какими реками лежит Междуречье?|Тигр и Евфрат|Нил и Тежу;Инд и Ганг;Хуанхэ и Янцзы','Как писали в Междуречье?|клинописью на глине|иероглифами на папирусе;буквами на бумаге;узелками','Кто записал свод законов в Вавилоне?|Хаммурапи|Хеопс;Дарий;Цезарь','Что придумали финикийцы?|алфавит|бумагу;порох;клинопись|Клинопись придумали в Междуречье, бумагу и порох — в Китае','Чем занимались финикийцы?|мореплаванием и торговлей|только земледелием;строили пирамиды;охотились на мамонтов','Что строили персидские цари, чтобы управлять огромной державой?|дороги и почту|пирамиды;Великую стену;акведуки']) },
 { id:'h5_6', t:'Древняя Индия и Китай',
   th:'В <b>Индии</b> (реки Инд и Ганг) придумали цифры, которые мы называем «арабскими», и знак нуля; там появилась игра — предок шахмат.<br>В <b>Китае</b> (реки Хуанхэ и Янцзы) изобрели <b>бумагу</b>, шёлк, компас. Император Цинь Шихуанди объединил страну и начал строить <b>Великую Китайскую стену</b>. Мудрец Конфуций учил уважать старших и учиться всю жизнь.',
   g: B(['Где придумали цифры, которыми мы пишем?|в Индии|в Египте;в Риме;в Португалии','Что изобрели в Древнем Китае?|бумагу|алфавит;пирамиды;олимпийские игры','Зачем строили Великую Китайскую стену?|для защиты от набегов кочевников|для защиты от наводнений;чтобы отделить Китай от Индии;как дорогу для торговых караванов','Предок какой игры появился в Индии?|шахматы|футбол;домино;теннис','Чему учил Конфуций?|уважать старших и учиться всю жизнь|воевать;строить пирамиды;плавать по морю','Какие реки текут в Китае?|Хуанхэ и Янцзы|Тигр и Евфрат;Нил и Конго;Инд и Ганг']) },
 { id:'h5_7', t:'Древняя Греция: мифы, Троя, Гомер',
   th:'Греки жили на Балканах и островах Эгейского моря. Поэт <b>Гомер</b> сложил поэмы «Илиада» (о Троянской войне) и «Одиссея» (о странствиях царя Одиссея).<br>По легенде, греки взяли Трою с помощью <b>деревянного коня</b>. На острове Крит жили мореплаватели, о них сложен миф о Минотавре и лабиринте.',
   g: B(['Кто автор «Илиады» и «Одиссеи»?|Гомер|Геродот;Сократ;Цезарь','Как, по легенде, греки взяли Трою?|с помощью деревянного коня|подкопом;пушками;голодом','О чём «Одиссея»?|о странствиях Одиссея|о строительстве пирамид;о войне с Римом;о путешествии в Индию','На каком острове жил, по мифу, Минотавр?|Крит|Сицилия;Мадейра;Британия','Какое море омывает Грецию?|Эгейское|Балтийское;Чёрное;Северное']) },
 { id:'h5_8', t:'Афины и Спарта. Олимпийские игры',
   th:'В <b>Афинах</b> возникла <b>демократия</b>: важные дела решало народное собрание граждан. В <b>Спарте</b> мальчиков с детства воспитывали воинами.<br>Первые Олимпийские игры прошли в 776 г. до н. э. в Олимпии. В 490 г. до н. э. греки победили персов при <b>Марафоне</b> — отсюда марафонский бег.<br>Греки строили театры, изучали математику (Пифагор) и философию (Сократ).',
   g: B(['Где возникла демократия?|в Афинах|в Спарте;в Египте;в Персии','Когда прошли первые Олимпийские игры в Древней Греции?|776 г. до н. э.|490 г. до н. э.;476 г.;1500 г. до н. э.|Современные Олимпийские игры возродили гораздо позже — в 1896 году','Как воспитывали мальчиков в Спарте?|воинами|художниками;торговцами;мореплавателями','В честь какой битвы назван марафонский бег?|битва при Марафоне|Троянская война;битва при Каннах;Куликовская битва','Кто такой Пифагор?|математик|полководец;царь Спарты;поэт «Илиады»','Что означает слово «демократия»?|власть народа|власть царя;власть жрецов;власть войска']) },
 { id:'h5_9', t:'Александр Македонский',
   th:'<b>Александр Македонский</b> (356–323 гг. до н. э.), ученик философа Аристотеля, в 20 лет стал царём Македонии. Он разгромил Персидскую державу и дошёл до Индии.<br>Основал много городов, самый известный — <b>Александрия</b> в Египте с огромной библиотекой и маяком — одним из семи чудес света.',
   g: B(['Кто был учителем Александра Македонского?|Аристотель|Гомер;Пифагор;Конфуций','До какой страны дошёл Александр со своим войском?|до Индии|до Португалии;до Китая;до Британии','Какой город он основал в Египте?|Александрию|Каир;Рим;Карфаген','Что было знаменито в Александрии?|библиотека и маяк|Колизей;пирамида Хеопса;Великая стена','Какую державу разгромил Александр?|Персидскую|Римскую;Китайскую;Карфагенскую']) },
 { id:'h5_10', t:'Древний Рим: город и республика',
   th:'По легенде, Рим основали братья <b>Ромул и Рем</b>, вскормленные волчицей, в 753 г. до н. э. В 509 г. до н. э. римляне изгнали царя — возникла <b>республика</b>: правили два консула и сенат.<br>Римляне строили дороги, акведуки (водопроводы), мосты. Их язык — <b>латынь</b>, от неё произошли португальский, испанский, итальянский, французский.',
   g: B(['Кто, по легенде, основал Рим?|Ромул и Рем|Цезарь и Август;Одиссей;Александр','Кто правил Римской республикой?|два консула и сенат|фараон;царь Спарты;император Китая','Что такое акведук?|водопровод|театр;корабль;крепость','Из какого языка произошёл португальский?|из латыни|из греческого;из арабского;из финикийского','В каком году, по легенде, основан Рим?|753 г. до н. э.|476 г.;1147 г.;776 г. до н. э.']) },
 { id:'h5_11', t:'Рим: Карфаген, Цезарь, империя',
   th:'Рим долго воевал с <b>Карфагеном</b>. Полководец Карфагена <b>Ганнибал</b> в 218 г. до н. э. перешёл со слонами через Альпы. В 146 г. до н. э. Карфаген был разрушен.<br><b>Юлий Цезарь</b> завоевал Галлию и стал диктатором; в 44 г. до н. э. его убили заговорщики. Его наследник <b>Октавиан Август</b> стал первым императором.<br>В Риме построили <b>Колизей</b> — амфитеатр на 50 тысяч зрителей.',
   g: B(['Кто перешёл через Альпы со слонами?|Ганнибал|Цезарь;Александр;Спартак','С каким городом Рим вёл долгие войны?|Карфаген|Афины;Вавилон;Александрия','Кто стал первым римским императором?|Октавиан Август|Юлий Цезарь;Ромул;Нерон','Что такое Колизей?|амфитеатр для зрелищ|храм;дворец императора;маяк','Какую страну завоевал Юлий Цезарь?|Галлию|Персию;Индию;Китай']) },
 { id:'h5_12', t:'Лузитания. Конец Западной Римской империи',
   th:'Римляне пришли на Пиренейский полуостров. Племена <b>лузитан</b> во главе с <b>Вириатом</b> долго им сопротивлялись. Потом здесь была римская провинция <b>Лузитания</b>; Лиссабон назывался <b>Олисипо</b>, в Эворе сохранился римский храм.<br>Империя ослабла и была разделена на Западную и Восточную. В <b>476 году</b> пала Западная Римская империя — этим годом заканчивается история Древнего мира.',
   g: B(['Как римляне называли Лиссабон?|Олисипо|Лузитания;Эвора;Карфаген','Кто возглавил борьбу лузитан против Рима?|Вириат|Ганнибал;Спартак;Ромул','В каком городе Португалии сохранился римский храм?|в Эворе|в Авейру;на Мадейре;на Азорах','Когда пала Западная Римская империя?|в 476 году|в 1500 году;в 753 г. до н. э.;в 1755 году','Как называлась римская провинция на месте Португалии?|Лузитания|Галлия;Британия;Македония']) }
];
/* ===== Мир вокруг нас — природоведение 5 кл. (1992), физическая география 5 кл. (1988), атлас (1991) ===== */
const A_GEO = [
 { id:'g5_1', t:'Земля во Вселенной',
   th:'Земля — третья планета от Солнца, одна из восьми. Солнце — звезда; свет от него идёт до Земли около 8 минут.<br>Луна — спутник Земли, оборот вокруг Земли около 27 суток, а полная смена её фаз (от новолуния до новолуния) — около 29,5 суток.',
   g: B(['Сколько минут идёт свет от Солнца до Земли?|около 8|около 1;около 60;мгновенно','Какая планета ближе всех к Солнцу?|Меркурий|Венера;Земля;Нептун','За сколько суток примерно Луна проходит все фазы?|29,5|7;365;1','Что такое звезда?|раскалённый газовый шар, излучающий свет|холодная планета;спутник;облако пыли','Какая самая большая планета Солнечной системы?|Юпитер|Сатурн;Земля;Нептун']) },
 { id:'g5_2', t:'План и карта. Масштаб',
   th:'<b>Масштаб</b> показывает, во сколько раз расстояние на карте меньше настоящего.<br>1 : 100 000 — в 1 см на карте 100 000 см = 1 км. 1 : 1 000 000 — в 1 см 10 км.',
   g: MIX(
     r => { const s=r.pick([1,2,5,10]), d=r.int(2,12); return N(`Масштаб 1 : ${U.big(s*100000)}. На карте ${d} см. Сколько это километров?`, s*d, `В 1 см — ${s} км`); },
     r => { const s=r.pick([1,2,5]), km=s*r.int(2,10); return N(`Масштаб 1 : ${U.big(s*100000)}. Расстояние ${km} км. Сколько это сантиметров на карте?`, km/s, `В 1 см — ${s} км`); },
     B(['На плане 1 см = 10 м. Это масштаб…|1 : 1 000|1 : 10;1 : 100;1 : 100 000','Как на карте показывают север?|вверху|внизу;слева;справа'])
   ) },
 { id:'g5_3', t:'Градусная сетка: широта и долгота',
   th:'<b>Широта</b> — расстояние от экватора к северу (с. ш.) или югу (ю. ш.), от 0° до 90°.<br><b>Долгота</b> — от нулевого (Гринвичского) меридиана к востоку (в. д.) или западу (з. д.), от 0° до 180°.<br>Лиссабон: около 39° с. ш., 9° з. д. Москва: 56° с. ш., 38° в. д.',
   g: B(['Какая широта у экватора?|0°|90°;180°;45°','Какая широта у Северного полюса?|90° с. ш.|0°;180°;45° с. ш.','Через какой город проходит нулевой меридиан?|Гринвич (Лондон)|Лиссабон;Париж;Москва','Лиссабон находится в…|северном и западном полушариях|южном и восточном;северном и восточном;южном и западном','Какой город севернее?|Москва (56° с. ш.)|Лиссабон (39° с. ш.);одинаково;нельзя сказать','Долгота отсчитывается от…|нулевого меридиана|экватора;полюса;тропика']) },
 { id:'g5_4', t:'Земная кора: горы, вулканы, землетрясения',
   th:'Земная кора состоит из плит, которые медленно движутся. На их границах бывают <b>землетрясения</b> и извержения <b>вулканов</b>.<br>В 1755 году Лиссабон разрушило сильное землетрясение и цунами. Азорские острова — вулканические, гора Пику (2 351 м) — самая высокая в Португалии. Самая высокая гора мира — Эверест (8 849 м).',
   g: B(['Что разрушило Лиссабон в 1755 году?|землетрясение и цунами|извержение Везувия;война;наводнение реки Дору','Самая высокая гора Португалии?|Пику на Азорах|Серра-да-Эштрела;Эверест;Монблан','Самая высокая гора мира?|Эверест|Эльбрус;Пику;Килиманджаро','Как появились Азорские острова?|из-за извержений вулканов|их насыпали люди;их принёс ледник;из кораллов','Почему бывают землетрясения?|движутся плиты земной коры|дует сильный ветер;Луна притягивает дома;идут дожди']) },
 { id:'g5_5', t:'Вода на Земле',
   th:'Почти 3/4 поверхности Земли покрыто водой. Самый большой и глубокий океан — <b>Тихий</b>, в нём Марианская впадина (около 11 км).<br>Самая длинная река — Нил (или Амазонка — споры идут), самая полноводная — Амазонка. Самая длинная река Пиренейского полуострова — Тежу (около 1 000 км).',
   g: B(['Какая часть поверхности Земли покрыта водой?|почти три четверти|половина;одна десятая;вся','Где находится самая глубокая впадина?|в Тихом океане|в Атлантическом;в Индийском;в Средиземном море','Самая полноводная река мира?|Амазонка|Тежу;Волга;Темза','Самая длинная река Пиренейского полуострова?|Тежу|Дору;Гвадиана;Эбро','Глубина Марианской впадины около…|11 км|1 км;100 м;50 км']) },
 { id:'g5_6', t:'Атмосфера и погода',
   th:'<b>Атмосфера</b> — воздушная оболочка Земли. С высотой воздух холоднее: примерно на 6° на каждый километр.<br>Погоду описывают температура, давление (барометр), ветер (флюгер), осадки, облачность. Климат Португалии — средиземноморский: жаркое сухое лето и мягкая дождливая зима.',
   g: MIX(
     r => { const t=r.int(15,30), h=r.int(1,4), sg=v=>(v>0?'+':v<0?'−':'')+Math.abs(v)+'°'; const v=t-6*h; return C(`У подножия горы +${t}°. Какая температура на высоте ${h} км (−6° на каждый км)?`, sg(v), [sg(v+6), sg(v-6), sg(t+6*h), sg(-v)], `${t} − 6 · ${h}`); },
     B(['Чем измеряют атмосферное давление?|барометром|термометром;флюгером;линейкой','Какой климат в Португалии?|средиземноморский|тропический;полярный;резко континентальный','Что такое атмосфера?|воздушная оболочка Земли|водная оболочка;земная кора;облака','Когда в Португалии больше всего дождей?|зимой|летом;весной;одинаково весь год'])
   ) },
 { id:'g5_7', t:'Природные зоны и живой мир',
   th:'Природные зоны меняются от экватора к полюсам: влажные леса, саванны, пустыни, степи, леса умеренного пояса, тайга, тундра, ледяные пустыни.<br>В Португалии растут пробковый дуб, оливы, эвкалипты, живут аисты, рыси (иберийская рысь — редкий вид).',
   g: B(['Какой редкий зверь живёт на Пиренейском полуострове?|иберийская рысь|белый медведь;кенгуру;панда','На каком материке больше всего саванн?|в Африке|в Антарктиде;в Евразии;в Северной Америке','Какое дерево — символ Португалии, его кору делают пробкой?|пробковый дуб|берёза;баобаб;кедр','Тайга — это зона…|хвойных лесов|пустынь;саванн;тропических лесов','Где нет деревьев из-за холода?|в тундре|в тайге;в саванне;в тропиках']) }
];

/* ===== Логика — по книге А. Г. Гайштута «Математика в логических упражнениях» (1985) ===== */
const A_LOGIC = [
 { id:'l5_1', t:'Числовые последовательности',
   th:'Ищи правило: прибавляют одно и то же? умножают? прибавляют всё больше? складывают два предыдущих?<br>1, 4, 9, 16, … — квадраты. 1, 1, 2, 3, 5, 8 — каждое число равно сумме двух предыдущих.',
   g: r => { const t=r.int(0,4); let s=[], rule='';
     if(t===0){const a=r.int(1,5),q=r.pick([2,3]);for(let i=0;i<6;i++)s.push(a*q**i);rule=`каждый раз ×${q}`;}
     else if(t===1){const k=r.int(1,6);for(let i=0;i<6;i++)s.push((k+i)**2);rule='квадраты чисел';}
     else if(t===2){let v=r.int(1,10),d=r.int(1,4);for(let i=0;i<6;i++){s.push(v);v+=d+i;}rule='прибавляют на 1 больше каждый раз';}
     else if(t===3){let a=r.int(1,5),b=r.int(1,5);s=[a,b];for(let i=2;i<6;i++)s.push(s[i-1]+s[i-2]);rule='сумма двух предыдущих';}
     else {const d=r.int(3,9),a=d*5+r.int(1,20);for(let i=0;i<6;i++)s.push(a-i*d);rule=`каждый раз −${d}`;}
     return N(`Какое число следующее? ${s.slice(0,5).join(', ')}, …`, s[5], rule); } },
 { id:'l5_2', t:'Логические выводы',
   th:'Если все A — это B, а X — это A, то X — тоже B. Но если все A — это B, из того, что X — это B, не следует, что X — это A.',
   g: B(['Все кошки — животные. Мурка — кошка. Значит…|Мурка — животное|Мурка — собака;все животные — кошки;ничего сказать нельзя','Все рыбы умеют плавать. Дельфин умеет плавать. Значит…|ничего определённого: это не доказывает, что дельфин — рыба|дельфин — рыба;дельфин не умеет плавать;все пловцы — рыбы','Некоторые ученики — отличники. Аня — ученица. Значит…|Аня может быть отличницей, а может и нет|Аня — отличница;Аня не отличница;все — отличники','Если идёт дождь, асфальт мокрый. Асфальт сухой. Значит…|дождя нет|дождь идёт;асфальт мокрый;ничего','Все квадраты — прямоугольники. Фигура не прямоугольник. Значит…|она не квадрат|она квадрат;она круг;ничего сказать нельзя']) },
 { id:'l5_3', t:'Задачи на смекалку',
   th:'Не спеши с ответом: представь ситуацию, нарисуй схему.',
   g: B(['Улитка ползёт на столб 10 м: днём +3 м, ночью −2 м. На какой день она будет на вершине?|на 8-й|на 10-й;на 7-й;на 9-й|За 7 суток она на 7 м, на 8-й день поднимется на 10 м','5 кошек ловят 5 мышей за 5 минут. Сколько кошек поймают 100 мышей за 100 минут?|5|100;20;25','Кувшинки на пруду удваиваются каждый день и закрывают пруд за 30 дней. Когда закрыли половину?|на 29-й день|на 15-й;на 10-й;на 28-й','В забеге ты обогнал второго. Каким ты стал?|вторым|первым;третьим;последним','У отца 6 сыновей, у каждого есть сестра. Сколько детей?|7|12;6;8','Книга стоит 1 евро и ещё половину своей цены. Сколько она стоит?|2 евро|1,5 евро;1 евро;3 евро','Сколько нулей в записи числа миллиард?|9|6;12;10']) },
 { id:'l5_4', t:'Комбинаторика',
   th:'Если первый выбор можно сделать a способами, а второй — b способами, то вместе — <b>a · b</b> способами.<br>Рукопожатия n человек: каждый жмёт руку (n − 1) людям, но каждое рукопожатие считается дважды: n · (n − 1) : 2.',
   g: MIX(
     r => { const n=r.int(4,10); return N(`Встретились ${n} друзей, и каждый пожал руку каждому. Сколько было рукопожатий?`, n*(n-1)/2, `${n} · ${n-1} : 2`); },
     r => { const a=r.int(2,5), b=r.int(2,5); return N(`У Ани ${a} ${U.pl(a,'юбка','юбки','юбок')} и ${b} ${U.pl(b,'кофта','кофты','кофт')}. Сколько разных нарядов (юбка + кофта) можно составить?`, a*b, `${a} · ${b}`); },
     B(['Сколько двузначных чисел можно составить из цифр 1, 2, 3, если цифры не повторяются?|6|9;3;5','Сколькими способами можно рассадить 3 человек на 3 стула?|6|3;9;1'])
   ) },
 { id:'l5_5', t:'Задачи на возраст и время',
   th:'Разница в возрасте не меняется со временем. Через x лет каждому станет на x лет больше.',
   g: MIX(
     r => { const d=r.int(6,12), x=r.int(1,10), m=2*d+x; return N(`Маме ${m} ${U.pl(m,'год','года','лет')}, дочке ${d} ${U.pl(d,'год','года','лет')}. Через сколько лет мама будет ровно вдвое старше дочки?`, x, `${m} + x = 2 · (${d} + x)`); },
     r => { const D=['понедельник','вторник','среда','четверг','пятница','суббота','воскресенье']; const i=r.int(0,6), n=r.int(10,40); const a=D[(i+n)%7]; return C(`Сегодня ${D[i]}. Какой день недели будет через ${n} ${U.pl(n,'день','дня','дней')}?`, a, r.sample(D.filter(x=>x!==a),3), `${n} = ${Math.floor(n/7)} · 7 + ${n%7}`); },
     r => { const a=r.int(8,15), b=r.int(2,a-1); return N(`Брату ${a} ${U.pl(a,'год','года','лет')}, сестре ${b}. Сколько лет будет брату, когда сестре исполнится ${a}?`, 2*a-b, `Разница ${a-b} не меняется`); }
   ) },
 { id:'l5_6', t:'Числовые загадки',
   th:'Решай «с конца»: делай обратные действия. □ · 7 + 5 = 47: сначала 47 − 5 = 42, потом 42 : 7 = 6.',
   g: r => { const x=r.int(2,12), a=r.int(2,9), b=r.int(1,20); return N(`Я задумала число, умножила его на ${a} и прибавила ${b}. Получилось ${x*a+b}. Какое число я задумала?`, x, `(${x*a+b} − ${b}) : ${a}`); } },
 { id:'l5_7', t:'Правдивые и лжецы',
   th:'Рыцари всегда говорят правду, лжецы всегда лгут. Проверяй каждую возможность: если считать человека рыцарем, нет ли противоречия?',
   g: B(['Человек говорит: «Я лжец». Может ли так сказать рыцарь или лжец?|никто из них|только рыцарь;только лжец;оба','A говорит: «B — лжец». B говорит: «Мы оба рыцари». Кто B?|лжец|рыцарь;нельзя определить;оба рыцари','Житель сказал: «Я рыцарь». Кто он?|нельзя определить|рыцарь;лжец;никто','A говорит: «Хотя бы один из нас лжец». Кто A?|рыцарь, а B — лжец|лжец;оба лжецы;оба рыцари']) }
];

/* ===== Português — Аня (A1–A2) ===== */
const PT_REG = { ar:['o','as','a','amos','am'], er:['o','es','e','emos','em'], ir:['o','es','e','imos','em'] };
const PT_PRET = { ar:['ei','aste','ou','ámos','aram'], er:['i','este','eu','emos','eram'], ir:['i','iste','iu','imos','iram'] };
const PT_PRON = ['eu','tu','ele / ela','nós','eles / elas'];
const PT_IRR = { ser:['sou','és','é','somos','são'], estar:['estou','estás','está','estamos','estão'], ter:['tenho','tens','tem','temos','têm'], ir:['vou','vais','vai','vamos','vão'], fazer:['faço','fazes','faz','fazemos','fazem'], poder:['posso','podes','pode','podemos','podem'], querer:['quero','queres','quer','queremos','querem'] };
const PT_VERBS = { ar:[['falar','говорить'],['cantar','петь'],['morar','жить'],['estudar','учиться'],['trabalhar','работать'],['nadar','плавать'],['jogar','играть'],['comprar','покупать']], er:[['comer','есть'],['beber','пить'],['correr','бегать'],['escrever','писать'],['aprender','учить(ся)'],['vender','продавать']], ir:[['partir','уезжать'],['abrir','открывать'],['decidir','решать'],['dividir','делить'],['assistir','смотреть, присутствовать']] };
function conjGen(table){ return r => { const g=r.pick(Object.keys(PT_VERBS).filter(k=>table===PT_REG||true)); const [v,ru]=r.pick(PT_VERBS[g]); const st=v.slice(0,-2); const forms=table[g].map(e=>st+e); const i=r.int(0,4); return Object.assign(C(`${PT_PRON[i]} ___ (${v} — ${ru})`, forms[i], r.sample(forms.filter((_,j)=>j!==i),3), `${v}: ${forms.join(', ')}`), {sp: PT_PRON[i].split(' ')[0]+' '+forms[i], spAfter:true}); }; }
const PT_A = [
 { id:'p5_1', t:'Artigos: o, a, os, as',
   th:'Мужской род: <b>o</b> livro, <b>um</b> livro. Женский: <b>a</b> mesa, <b>uma</b> mesa. Множественное: <b>os</b> livros, <b>as</b> mesas.<br>Исключения: <b>a</b> mão (рука), <b>o</b> dia (день), <b>o</b> mapa, <b>o</b> problema.',
   g: r => { const W=[['livro','o'],['mesa','a'],['mão','a'],['dia','o'],['flor','a'],['mapa','o'],['cidade','a'],['problema','o'],['lição','a'],['coração','o'],['viagem','a'],['sol','o'],['lua','a'],['água','a'],['leite','o'],['árvore','a'],['carro','o'],['ponte','a'],['país','o']]; const [w,a]=r.pick(W); return Object.assign(C(`Какой артикль: ___ ${w}?`, a, [a==='o'?'a':'o'], `${a} ${w}`), {sp:`${a} ${w}`, spAfter:true}); } },
 { id:'p5_2', t:'Plural — множественное число',
   th:'Обычно + <b>s</b>: livro → livros. На согласный + <b>es</b>: flor → flores, mês → meses.<br>-al, -ol → <b>-ais, -óis</b>: animal → animais. -ão → <b>-ões, -ães, -ãos</b>: lição → lições, pão → pães, mão → mãos. -m → <b>-ns</b>: homem → homens.',
   g: B(['Plural de «flor»|flores|flors;floris;flore','Plural de «animal»|animais|animals;animales;animaus','Plural de «pão»|pães|pãos;pões;pãoes','Plural de «mão»|mãos|mães;mões;mãoes','Plural de «lição»|lições|lição;liçãos;liçãoes','Plural de «homem»|homens|homems;homemes;homes','Plural de «papel»|papéis|papels;papeles;papeis s','Plural de «mês»|meses|mêss;mes;mêses']) },
 { id:'p5_3', t:'Ser e estar',
   th:'<b>Ser</b> — постоянное: кто ты, откуда, какой по характеру. Eu <b>sou</b> a Anya. <b>Sou</b> russa.<br><b>Estar</b> — временное состояние и место: <b>Estou</b> cansada. A mãe <b>está</b> em casa.<br>ser: sou, és, é, somos, são. estar: estou, estás, está, estamos, estão.',
   g: B(['Eu ___ a Anya.|sou|estou;é;está','Hoje eu ___ cansada.|estou|sou;é;somos','A mãe ___ em casa.|está|é;sou;são','Nós ___ de Portugal.|somos|estamos;são;está','O céu ___ azul hoje, sem nuvens.|está|é;sou;são','Lisboa ___ a capital de Portugal.|é|está;sou;estão','Tu ___ muito simpática, sempre foste assim.|és|estou;é;sou','Eles ___ na escola agora.|estão|são;está;somos']) },
 { id:'p5_4', t:'Presente: verbos em -ar', th:'falar → eu fal<b>o</b>, tu fal<b>as</b>, ele fal<b>a</b>, nós fal<b>amos</b>, eles fal<b>am</b>.', g: r => { const sav=PT_VERBS; const [v,ru]=r.pick(sav.ar); const st=v.slice(0,-2); const f=PT_REG.ar.map(e=>st+e); const i=r.int(0,4); return Object.assign(C(`${PT_PRON[i]} ___ (${v} — ${ru})`, f[i], r.sample(f.filter((_,j)=>j!==i),3), `${v}: ${f.join(', ')}`), {sp:PT_PRON[i].split(' ')[0]+' '+f[i], spAfter:true}); } },
 { id:'p5_5', t:'Presente: verbos em -er e -ir', th:'comer → com<b>o</b>, com<b>es</b>, com<b>e</b>, com<b>emos</b>, com<b>em</b>.<br>partir → part<b>o</b>, part<b>es</b>, part<b>e</b>, part<b>imos</b>, part<b>em</b>.', g: r => { const g=r.pick(['er','ir']); const [v,ru]=r.pick(PT_VERBS[g]); const st=v.slice(0,-2); const f=PT_REG[g].map(e=>st+e); const i=r.int(0,4); return Object.assign(C(`${PT_PRON[i]} ___ (${v} — ${ru})`, f[i], r.sample(f.filter((_,j)=>j!==i),3), `${v}: ${f.join(', ')}`), {sp:PT_PRON[i].split(' ')[0]+' '+f[i], spAfter:true}); } },
 { id:'p5_6', t:'Verbos irregulares: ter, ir, fazer, poder, querer',
   th:'ter: tenho, tens, tem, temos, têm. ir: vou, vais, vai, vamos, vão.<br>fazer: faço, fazes, faz, fazemos, fazem. poder: posso, podes, pode, podemos, podem. querer: quero, queres, quer, queremos, querem.',
   g: r => { const v=r.pick(Object.keys(PT_IRR).filter(k=>k!=='ser'&&k!=='estar')); const f=PT_IRR[v]; const i=r.int(0,4); return Object.assign(C(`${PT_PRON[i]} ___ (${v})`, f[i], r.sample(f.filter((_,j)=>j!==i),3), `${v}: ${f.join(', ')}`), {sp:PT_PRON[i].split(' ')[0]+' '+f[i], spAfter:true}); } },
 { id:'p5_7', t:'Números até 1000', th:'cem (100), cento e um (101), duzentos (200), trezentos, quatrocentos, quinhentos (500), seiscentos, setecentos, oitocentos, novecentos, mil (1000).<br>345 = trezentos <b>e</b> quarenta <b>e</b> cinco.',
   g: r => { const n=r.int(101,999); if(r()<.5) return Object.assign(N(`Какое число: <span class="pt">${ptNum(n)}</span>?`, n, ''), {sp:ptNum(n)}); const w=[n+100>999?n-100:n+100, n%10===9?n-1:n+1, n+10>999?n-10:n+10]; return Object.assign(C(`Como se escreve ${n}?`, ptNum(n), w.map(ptNum)), {sp:ptNum(n), spAfter:true}); } },
 { id:'p5_8', t:'As horas — время',
   th:'Que horas são? — São <b>três horas</b> (3:00). É <b>uma hora</b> (1:00). São três <b>e meia</b> (3:30). São três <b>e um quarto</b> (3:15). São quatro <b>menos um quarto</b> (3:45). É <b>meio-dia</b> (12:00), é <b>meia-noite</b> (0:00).',
   g: B(['São três e meia.|3:30|3:15;3:45;2:30','São duas e um quarto.|2:15|2:45;1:15;2:30','São cinco menos um quarto.|4:45|5:15;5:45;4:15','É meio-dia.|12:00|0:00;6:00;12:30','É uma hora.|1:00|11:00;1:30;12:00','São dez horas.|10:00|2:00;12:00;10:30']) },
 { id:'p5_9', t:'Preposições: em, de, a + artigo',
   th:'em + o = <b>no</b>, em + a = <b>na</b>: no parque, na escola.<br>de + o = <b>do</b>, de + a = <b>da</b>: o livro do João, a casa da avó.<br>a + o = <b>ao</b>, a + a = <b>à</b>: vou ao cinema, vou à praia.',
   g: B(['Estou ___ escola.|na|no;da;à','Vou ___ praia.|à|na;ao;da','O livro ___ professor.|do|da;no;ao','Moro ___ Porto.|no|na;ao;do','Vamos ___ cinema.|ao|à;no;do','A casa ___ avó.|da|do;na;à']) },
 { id:'p5_10', t:'Frases do dia a dia',
   th:'Фразы для школы и улицы. Нажми, чтобы послушать.',
   g: vocabGen([['Como te chamas?','Как тебя зовут?'],['Quantos anos tens?','Сколько тебе лет?'],['Onde moras?','Где ты живёшь?'],['Não percebo.','Я не понимаю.'],['Pode repetir, por favor?','Повторите, пожалуйста.'],['Qual é a tua disciplina preferida?','Какой твой любимый предмет?'],['Hoje está a chover.','Сегодня идёт дождь.'],['Amanhã temos teste de Matemática.','Завтра у нас контрольная по математике.'],['Esqueci-me do caderno.','Я забыла тетрадь.'],['Estou atrasada.','Я опаздываю.'],['Concordo contigo.','Я с тобой согласна.'],['Quanto custa?','Сколько стоит?']]) },
 { id:'p5_11', t:'Pretérito perfeito — прошедшее время',
   th:'falar → fal<b>ei</b>, fal<b>aste</b>, fal<b>ou</b>, fal<b>ámos</b>, fal<b>aram</b>.<br>comer → com<b>i</b>, com<b>este</b>, com<b>eu</b>, com<b>emos</b>, com<b>eram</b>.<br>partir → part<b>i</b>, part<b>iste</b>, part<b>iu</b>, part<b>imos</b>, part<b>iram</b>.<br>Ontem eu <b>estudei</b> muito.',
   g: r => { const g=r.pick(['ar','er','ir']); const [v,ru]=r.pick(PT_VERBS[g]); const st=v.slice(0,-2); const f=PT_PRET[g].map(e=>(st+e).replace(/gei$/,'guei').replace(/cei$/,'quei').replace(/çei$/,'cei')); const i=r.int(0,4); return Object.assign(C(`Ontem ${PT_PRON[i]} ___ (${v} — ${ru})`, f[i], r.sample(f.filter((_,j)=>j!==i),3), `${v}: ${f.join(', ')}`), {sp:PT_PRON[i].split(' ')[0]+' '+f[i], spAfter:true}); } }
];

